+// Utilities for slicing markdown by exact section heading lines.
+// Brief 01 requires anchored regex on whole heading lines (no indexOf).
+
+function escapeRegExp(str) {
+  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+}
+
+/**
+ * Return the markdown content inside the section whose heading line is exactly
+ * `heading` (e.g. "## Transaction Ledger"). The returned string does not
+ * include the heading line.
+ */
+function sliceSection(markdown, heading) {
+  const headingRe = new RegExp(`^${escapeRegExp(heading)}\\s*$`, "m");
+  const match = markdown.match(headingRe);
+  if (!match || match.index == null) return "";
+
+  // Start after the heading line.
+  const afterHeadingIdx = markdown.indexOf("\n", match.index) + 1;
+  if (afterHeadingIdx <= 0) return "";
+
+  // End at the next level-2 heading (## ...) or EOF.
+  const rest = markdown.slice(afterHeadingIdx);
+  const nextHeadingMatch = rest.match(/^##\s+/m);
+  const endIdx =
+    nextHeadingMatch && nextHeadingMatch.index != null
+      ? afterHeadingIdx + nextHeadingMatch.index
+      : markdown.length;
+
+  return markdown.slice(afterHeadingIdx, endIdx);
+}
+
+module.exports = { sliceSection };
