function parseLedger(markdown) {
  const slice = sliceSection(markdown, "## Transaction Ledger");
  if (!slice) return [];

  // Keep last non-provisional block per transaction_id (Brief 01).
  const byId = new Map();
  const blocks = slice.split(/^###\s+/m).slice(1);

  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = lines[0].trim();
    if (!transactionId.startsWith("TXN-")) continue;

    // Ignore provisional blocks (case-insensitive) (Brief 01).
    if (/^provisional:\s*true\s*$/im.test(block)) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.toLowerCase().startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
